)
foreach($m in $mains){
  $ok=$false; for($i=0;$i -lt 5 -and -not $ok;$i++){ $o=lark-cli base +record-list --base-token $base --table-id $m.id --field-id 货币类型 --limit 200 --format json; if($LASTEXITCODE -eq 0){$ok=$true} else {Start-Sleep -Milliseconds 800} }
  if($ok){
    $j=$o|ConvertFrom-Json
    $rows=$j.data.data
    $vals=@(); foreach($r in $rows){ $c=$r[0]; if($c){ if($c -is [array]){$vals+=$c[0]}else{$vals+=$c} } }
    $u=$vals | Group-Object | ForEach-Object { "$($_.Name)×$($_.Count)" }
    "$($m.n): 共$($rows.Count)行, 货币类型 = " + ($u -join ", ")
  } else { "$($m.n): FAILED/无货币类型字段" }
}

